/* Receiver Crosswind: shared geometry, save-safe state and reversible cover.
 * Model helpers only. Neither presentation nor this module grants progression. */
export const WINDBREAK_CONTROLS=Object.freeze([
 {id:'bell-windbreak-west',kind:'windbreak',name:'Windbreak selector',x:-112,y:27.5,z:-3.5},
 {id:'bell-windbreak-east',kind:'windbreak',name:'Windbreak selector',x:-102,y:27.5,z:-3.5}
]);
// East screens the gallery approach from the longshot; west screens the receiver.
// Neither position blocks every attacker or both flanking lanes.
export const WINDBREAK_SCREENS=Object.freeze([
 Object.freeze({id:'bell-windbreak',x1:-106,x2:-105.6,y1:27.5,y2:30,z1:-13.5,z2:-9.5}),
 Object.freeze({id:'bell-windbreak',x1:-112.8,x2:-108,y1:27.5,y2:30,z1:-11.9,z2:-11.5})
]);
export const windbreakMode=s=>s?.bellwether?.windbreak===1?1:0;
export const windbreakSolid=s=>WINDBREAK_SCREENS[windbreakMode(s)];
export function overlapsWindbreak(p,box,r=.45,height=1.8){
 return p&&p.x+r>box.x1&&p.x-r<box.x2&&p.z+r>box.z1&&p.z-r<box.z2&&p.y+height>box.y1&&p.y<box.y2;
}
export function canShiftWindbreak(s){
 const next=WINDBREAK_SCREENS[1-windbreakMode(s)];
 // Interlock: never close a destination panel through the courier or a live NPC.
 return !overlapsWindbreak(s.p,next,.45,s.p.crouched?1.04:1.8)&&!s.drones.some(e=>e.hp>0&&overlapsWindbreak({...e,y:e.humanoid?e.y-1.05:e.y-.5},next,.6,e.humanoid?1.8:1));
}
export function windbreakSnapshot(s){
 const mode=windbreakMode(s);
 return {mode,label:mode?'Receiver shelter':'Gallery shelter',powered:(s?.bellwether?.stage||0)>=3,solid:windbreakSolid(s),switches:s?.bellwether?.windbreakSwitches||0,blocked:s?.bellwether?.windbreakBlocked||0,retreats:s?.bellwether?.galleryRetreats||0};
}
export function inReceiverEncounter(p){
 // The existing east maintenance stair/landing is a recovery, not abandonment.
 const roof=p.y>=24&&p.y<=38&&Math.abs(p.x+107)<=18&&Math.abs(p.z+9)<=20;
 const gallery=p.y>=21&&p.y<29&&p.x>=-103&&p.x<=-97&&p.z>=-21&&p.z<=-4;
 return roof||gallery;
}

/* Graybox-quality functional cues; solids are imported from the model contract. */
import {createFoundryKit} from './foundry-kit.mjs';
import {WINDBREAK_CONTROLS,WINDBREAK_SCREENS,windbreakSnapshot} from './bellwether-windbreak.mjs';
export function installWindbreak(scene,clearLine){
 const k=createFoundryKit(scene),{root,add,batch,sign}=k;root.name='Receiver Crosswind / reversible storm screens';
 const screens=WINDBREAK_SCREENS.map((b,i)=>{
  const w=b.x2-b.x1,d=b.z2-b.z1,h=b.y2-b.y1,x=(b.x1+b.x2)/2,z=(b.z1+b.z2)/2;
  const screen=add('box','metal',[x,b.y1+h/2,z],[w,h,d]);screen.name='windbreak-'+i;
  // Recessed tracks show where the other panel can rise without blocking feet.
  batch('box','brass',[x,b.y1+.025,z],[w+.16,.05,d+.16]);
  const stripe=add('box','paper',[0,.32,0],[1.03,.06,1.03],screen);
  stripe.name='windbreak-warning-stripe';
  return screen;
 });
 const handles=[],signals=[];
 for(const q of WINDBREAK_CONTROLS){
  batch('cylinder','metal',[q.x,q.y+.5,q.z-.45],[.12,1,.12]);
  const lever=add('box','brass',[q.x,q.y+1.05,q.z-.45],[.12,.5,.12]);handles.push(lever);
  signals.push([add('sphere','glow',[q.x-.22,q.y+1.5,q.z-.45],[.07,.07,.07]),add('sphere','glow',[q.x+.22,q.y+1.5,q.z-.45],[.07,.07,.07])]);
  sign('WINDBREAK / GALLERY < > RECEIVER',q.x,q.y+2.3,q.z-.5,4.6);
 }
 // Arrow rails and a fixed landmark establish both exits before combat starts.
 sign('GALLERY / RETREAT AND RETURN',-100.5,29.8,-5.1,3.8);
 sign('SOUTH LADDER / MARKET',-107,29.9,-1.85,4);
 sign('STORM SCREENS / COVER ALSO BLOCKS YOUR SHOTS',-109.8,31,-16.3,7);
 k.flush();let status=windbreakSnapshot(null);
 function update(s){status=windbreakSnapshot(s);status.sightlines=s.drones.filter(e=>e.bellwetherEnemy&&e.hp>0).map(e=>({id:e.id,clear:clearLine({...s.p,y:s.p.y+1.35},e,s)}));screens.forEach((m,i)=>m.visible=i===status.mode);handles.forEach(m=>m.rotation.z=status.mode?-.55:.55);signals.forEach(l=>l.forEach((m,i)=>m.visible=status.powered&&i===status.mode));}
 return {update,stats:()=>status,dispose:k.dispose};
}

if(WINDBREAK_CONTROLS.some(q=>q.id===id)){
 if(!canShiftWindbreak(s)){b.windbreakBlocked=(b.windbreakBlocked||0)+1;say(s,'Windbreak interlock: the rising screen is occupied. Step clear or let the guard move; nothing was closed.');return false;}
 b.windbreak=1-windbreakMode(s);b.windbreakSwitches=(b.windbreakSwitches||0)+1;
 say(s,b.windbreak?'Receiver screened from the north. Your shots are blocked too; use the open east flank. The gallery approach is exposed.':'Gallery screened from the northwest. The receiver lane is open for shots in both directions.');
 emit(s,'bell-windbreak',{mode:b.windbreak,at:WINDBREAK_CONTROLS.find(q=>q.id===id)});save(s);return true;
}
